-- Migration 37: Replace the storefront catalogue with the owner's fragrance list
-- ══════════════════════════════════════════════════════════════════════════════════════
-- Source: "Fragrance List.xlsx" (139 rows) supplied by the store owner.
--
-- What this file does:
--   1. Relaxes order_items -> products from ON DELETE RESTRICT to ON DELETE SET NULL, so a
--      product can be retired without blocking on historic orders (this also fixes the admin
--      panel's Delete Product button, which previously errored on any product ever ordered).
--   2. Removes EVERY product currently in the store, together with its inventory, collection
--      mappings and wishlist entries. Orders and order_items survive; their product link is
--      set to NULL.
--   3. Inserts all 138 products from the spreadsheet with their exact top / middle / base
--      notes, brand, gender and bottle size.
--   4. Rebuilds inventory rows, brand collections, line collections and the curated shelves.
--
-- Rows 92 and 93 of the sheet are the same fragrance (Armaf Club de Nuit Intense Man) in two
-- bottle sizes, so they become ONE product with sizes 105ml and 200ml. 139 rows -> 138 products.
--
-- Not in the spreadsheet, so seeded as placeholders for the admin panel to overwrite:
--   price       AED 199.00 for every product
--   image_url   /placeholder-bottle.png (the owner uploads real photography from the back end)
--   is_new / is_bestseller  a small starter curation so the homepage shelves are not empty
--   stock       25 units per size, low-stock threshold 5

-- ── 1. Let products be retired without blocking on order history ────────────────────────────
ALTER TABLE public.order_items DROP CONSTRAINT IF EXISTS order_items_product_id_fkey;
ALTER TABLE public.order_items
    ADD CONSTRAINT order_items_product_id_fkey
    FOREIGN KEY (product_id) REFERENCES public.products(id) ON DELETE SET NULL;

-- ── 2. Clear the existing catalogue ─────────────────────────────────────────────────────────
DELETE FROM public.wishlists;
DELETE FROM public.product_collections;
DELETE FROM public.inventory;
DELETE FROM public.products;

-- ── 3. Collections the new catalogue needs ──────────────────────────────────────────────────
-- Rasasi's La Yuqawam pair had no line collection yet.
INSERT INTO public.collections (id, title, description, cover_image, type, kind, parent_id, sort_order) VALUES
    ('la-yuqawam', 'La Yuqawam', 'La Yuqawam pour Homme and pour Femme.', NULL, 'manual', 'line', 'rasasi', 14)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, description = EXCLUDED.description,
    kind = EXCLUDED.kind, parent_id = EXCLUDED.parent_id, sort_order = EXCLUDED.sort_order;

-- Line titles now follow the spreadsheet's spelling.
UPDATE public.collections SET title = 'Daarej'   WHERE id = 'dareej';
UPDATE public.collections SET title = 'Maahir'   WHERE id = 'mahir';
UPDATE public.collections SET title = 'Musamam'  WHERE id = 'musammam';
UPDATE public.collections SET title = 'Al Noble' WHERE id = 'noble';
UPDATE public.collections SET title = 'Precieux' WHERE id = 'precioux';

-- The house's own GHARIB label is not part of the new catalogue, so its brand page goes too.
DELETE FROM public.collections WHERE id = 'gharib';

-- ── 4. Products ─────────────────────────────────────────────────────────────────────────────
