-- ── 5. Inventory: one sellable stock row per product and size ───────────────────────────────
INSERT INTO public.inventory (product_id, size, stock_level, low_stock_threshold)
SELECT p.id, s, 25, 5
FROM public.products p, unnest(p.sizes) AS s
ON CONFLICT (product_id, size) DO NOTHING;

-- ── 6. Brand collections ────────────────────────────────────────────────────────────────────
INSERT INTO public.product_collections (product_id, collection_id)
SELECT p.id, c.id
FROM public.products p
JOIN public.collections c ON c.kind = 'brand' AND c.brand = p.brand
ON CONFLICT DO NOTHING;

-- ── 7. Line collections ─────────────────────────────────────────────────────────────────────
INSERT INTO public.product_collections (product_id, collection_id)
SELECT p.id, l.collection_id
FROM public.products p
JOIN (VALUES
    ('hawas', ARRAY[3000, 3001, 3002, 3004, 3005, 3006, 3007, 3008, 3009, 3010, 3011, 3012, 3013, 3014, 3015, 3016, 3017, 3018, 3019, 3020, 3021, 3022, 3023, 3024, 3025, 3026, 3027, 3028]),
    ('rasasi-blue', ARRAY[3029, 3030]),
    ('la-yuqawam', ARRAY[3031, 3032]),
    ('dareej', ARRAY[3033, 3034, 3035, 3036, 3037]),
    ('khamrah', ARRAY[3100, 3101, 3102]),
    ('yara', ARRAY[3103, 3104, 3105, 3106, 3107]),
    ('asad', ARRAY[3108, 3109, 3110]),
    ('badee-al-oud', ARRAY[3111, 3112, 3113, 3114, 3115]),
    ('fakhar', ARRAY[3116, 3117, 3118, 3119]),
    ('ameerat-al-arab', ARRAY[3120, 3121, 3122]),
    ('ana-abiyedh', ARRAY[3123, 3124, 3125]),
