    ('hayaati', ARRAY[3146, 3147, 3148, 3149]),
    ('rave-now', ARRAY[3150, 3151]),
    ('club-de-nuit', ARRAY[3200, 3201, 3202, 3203, 3204, 3205, 3206, 3207, 3208, 3209, 3210, 3211, 3212]),
    ('precioux', ARRAY[3211, 3212]),
    ('odyssey', ARRAY[3213, 3214, 3215, 3216, 3217, 3218, 3219, 3220, 3221, 3222]),
