-- ── 8. Curated shelves ──────────────────────────────────────────────────────────────────────
-- Starter merchandising only — flip is_new / is_bestseller from the admin panel and these
-- shelves follow. 'trending' mirrors the homepage rule (bestseller OR new).
INSERT INTO public.product_collections (product_id, collection_id)
SELECT id, 'bestsellers' FROM public.products WHERE is_bestseller
ON CONFLICT DO NOTHING;

INSERT INTO public.product_collections (product_id, collection_id)
SELECT id, 'new' FROM public.products WHERE is_new
ON CONFLICT DO NOTHING;

INSERT INTO public.product_collections (product_id, collection_id)
SELECT id, 'trending' FROM public.products WHERE is_new OR is_bestseller
ON CONFLICT DO NOTHING;

-- 'favorites' ships as the Exclusive Offers shelf: one flagship per house.
INSERT INTO public.product_collections (product_id, collection_id)
SELECT id, 'favorites' FROM public.products WHERE id IN (3000, 3100, 3200, 3300, 3400, 3500)
ON CONFLICT DO NOTHING;

-- The automated Oud Vault repopulates from the tag, exactly as migration 13 defined it.
INSERT INTO public.product_collections (product_id, collection_id)
SELECT id, 'smart-ouds' FROM public.products WHERE 'oud' = ANY(tags)
ON CONFLICT DO NOTHING;

-- ── 9. Keep admin-created products clear of the seeded id range ─────────────────────────────
SELECT setval(
    pg_get_serial_sequence('public.products', 'id'),
    GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.products), 4000),
    true
);
